	@Test
	public void nestedOptionalChainsWithRepeatedInnerKeysProbeFarLessWithTheCache() {
		String query = chainQuery();
		List<BindingSet> reference = evaluate(query, false, true);

		assertThat(reference).isNotEmpty();
		assertThat(evaluate(query, true, false)).containsExactlyInAnyOrderElementsOf(reference);
		assertThat(evaluate(query, true, true)).containsExactlyInAnyOrderElementsOf(reference);

		long uncachedOpens = metric(query, false, SCAN_OPENS);
		long cachedOpens = metric(query, true, SCAN_OPENS);
		assertThat(uncachedOpens).as("control run must probe per row").isGreaterThan(ROOTS);
		// the root-correlated probes (one per unique ?a) cannot be shared; everything keyed by ?l, ?m must be
		assertThat(cachedOpens).as("cached run must probe per distinct key").isLessThan(uncachedOpens / 2);
		assertThat(metric(query, true, REPLAYS)).isGreaterThan(0L);
	}

	@Test
	public void unboundKeysEmptyRightSidesAndSharedVariablesMatchTheUncachedPath() {
		for (String query : List.of(unboundKeyQuery(), emptyRightSideQuery(), siblingOptionalQuery())) {
			List<BindingSet> reference = evaluate(query, false, true);
			assertThat(reference).as(query).isNotEmpty();
			assertThat(evaluate(query, true, false)).as(query).containsExactlyInAnyOrderElementsOf(reference);
			assertThat(evaluate(query, true, true)).as(query).containsExactlyInAnyOrderElementsOf(reference);
		}
	}

	@Test
	public void multiRowSiblingOptionalsAfterRepeatedKeysResumeCorrectly() {
		// sibling OPTIONALs with multi-row arms follow groups whose inner keys repeat: the streaming kernel pauses
		// inside those arms, so a replayed or recorded row must never be re-entered or recorded twice
		String query = prefix() + String.join("\n",
				"SELECT DISTINCT ?a ?o ?oid ?m ?mid ?s ?sid ?sib ?sibid WHERE {",
				"  ?a a ex:A .",
				"  OPTIONAL { ?a ex:owner ?o . OPTIONAL { ?o ex:id ?oid } }",
				"  OPTIONAL { ?a ex:link ?l . ?l ex:member ?m . OPTIONAL { ?m ex:id ?mid } }",
				"  OPTIONAL { ?a ex:link ?l2 . ?l2 ex:member ?m2 . OPTIONAL { ?m2 ex:stage ?s . ?s ex:id ?sid } }",
				"  OPTIONAL { ?a ex:sibling ?sib . OPTIONAL { ?sib ex:id ?sibid } }",
				"} ORDER BY ?a");
		List<BindingSet> reference = evaluate(query, false, true);

		assertThat(reference).isNotEmpty();
		assertThat(evaluate(query, true, false)).containsExactlyInAnyOrderElementsOf(reference);
		assertThat(evaluate(query, true, true)).containsExactlyInAnyOrderElementsOf(reference);
	}

	@Test
	public void uniqueKeysSwitchTheCacheOffWithoutChangingResults() {
		String query = uniqueKeyQuery();
		List<BindingSet> reference = evaluate(query, false, true);

		assertThat(reference).hasSize(ROOTS);
		assertThat(evaluate(query, true, true)).containsExactlyInAnyOrderElementsOf(reference);
		assertThat(metric(query, true, REPLAYS)).isZero();
		assertThat(metric(query, true, BYPASSES)).isGreaterThan(0L);
	}

