	private static String prefix() {
		return "PREFIX ex: <" + EX + ">\n";
	}

	static String chainQuery() {
		return prefix() + String.join("\n",
				"SELECT DISTINCT ?a ?aid ?o ?oid ?l ?lid ?m ?mid ?s ?sid WHERE {",
				"  ?a a ex:A . ?a ex:id ?aid .",
				"  OPTIONAL { ?a ex:owner ?o . ?o ex:id ?oid }",
				"  OPTIONAL { ?a ex:link ?l . ?l ex:id ?lid",
				"    OPTIONAL { ?l ex:member ?m . ?m ex:id ?mid",
				"      OPTIONAL { ?m ex:stage ?s . ?s ex:id ?sid } } }",
				"}");
	}

	private static String unboundKeyQuery() {
		// ?o is unbound for every 7th root, so the following OPTIONAL is correlated on an unbound key
		return prefix() + String.join("\n",
				"SELECT DISTINCT ?a ?o ?m ?mid WHERE {",
				"  ?a a ex:A .",
				"  OPTIONAL { ?a ex:owner ?o }",
				"  OPTIONAL { ?o ex:stage ?m . ?m ex:id ?mid }",
				"}");
	}

	private static String emptyRightSideQuery() {
		return prefix() + String.join("\n",
				"SELECT DISTINCT ?a ?x ?y WHERE {",
				"  ?a a ex:A .",
				"  OPTIONAL { ?a ex:link ?l . ?l ex:missing ?x . OPTIONAL { ?x ex:id ?y } }",
				"}");
	}

	private static String siblingOptionalQuery() {
		return prefix() + String.join("\n",
				"SELECT ?a ?s ?sid ?o WHERE {",
				"  ?a a ex:A .",
				"  OPTIONAL { ?a ex:sibling ?s . ?s ex:id ?sid }",
				"  OPTIONAL { ?a ex:owner ?o }",
				"}");
	}

	private static String uniqueKeyQuery() {
		return prefix() + String.join("\n",
				"SELECT DISTINCT ?a ?aid ?u ?uid WHERE {",
				"  ?a a ex:A . ?a ex:id ?aid .",
				"  OPTIONAL { ?a ex:unique ?u . ?u ex:id ?uid }",
				"}");
	}

	private List<BindingSet> evaluate(String query, boolean nativeEngine, boolean replay) {
		System.setProperty(NATIVE_FLAG, Boolean.toString(nativeEngine));
		System.setProperty(REPLAY, Boolean.toString(replay));
		try (SailRepositoryConnection connection = repository.getConnection()) {
			if (nativeEngine) {
				try {
					SailTupleQuery forced = (SailTupleQuery) connection.prepareTupleQuery(query);
					forced.setForcedLmdbExecutionStrategy(forcedStrategy());
					return QueryResults.asList(forced.evaluate());
				} catch (QueryEvaluationException e) {
					// small shapes decline the forced strategy ("no operator fusion opportunity"); the ordinary
					// native engine still has to agree with the generic engine
					if (!String.valueOf(e.getMessage()).contains("could not be forced")) {
						throw e;
					}
				}
			}
			return QueryResults.asList(connection.prepareTupleQuery(query).evaluate());
		} finally {
			System.setProperty(NATIVE_FLAG, "true");
		}
	}

	protected long metric(String query, boolean replay, String name) {
		return metric(query, replay, name, forcedStrategy());
	}

	protected long metric(String query, boolean replay, String name, String strategy) {
		System.setProperty(REPLAY, Boolean.toString(replay));
		try (SailRepositoryConnection connection = repository.getConnection()) {
			SailTupleQuery prepared = (SailTupleQuery) connection.prepareTupleQuery(query);
			prepared.setForcedLmdbExecutionStrategy(strategy);
			GenericPlanNode plan;
			try {
				plan = prepared.explain(Explanation.Level.Telemetry).toGenericPlanNode();
			} catch (QueryEvaluationException e) {
				if (!String.valueOf(e.getMessage()).contains("could not be forced")) {
					throw e;
				}
				plan = connection.prepareTupleQuery(query).explain(Explanation.Level.Telemetry).toGenericPlanNode();
			}
			return sum(plan, name);
		}
	}

	protected static long sum(GenericPlanNode node, String name) {
		if (node == null) {
			return 0L;
		}
		Long own = node.getLongMetricActual(name);
		long total = own == null ? 0L : own;
		if (node.getPlans() != null) {
			for (GenericPlanNode child : node.getPlans()) {
				total += sum(child, name);
			}
		}
		return total;
	}
